<script setup lang="ts">
import { computed, onMounted } from 'vue'
import { RouterLink, useRoute } from 'vue-router'
import { Building2, MapPin, Ruler, CalendarDays, Pencil, MessageSquare } from '@lucide/vue'
import AppSidebar from '@/components/layout/AppSidebar.vue'
import { getBrokerListing, getEditableBrokerListing, loadBrokerListings } from '@/stores/brokerListings'
import { formatBrokerPrice } from '@/data/broker/brokerListings'
const route = useRoute()
const id = computed(() => Number(route.params.id))
const listing = computed(() => getBrokerListing(id.value))
const editable = computed(() => !!getEditableBrokerListing(id.value))
onMounted(() => loadBrokerListings())
</script>
<template><AppSidebar role="broker"><main class="page"><RouterLink to="/broker/listings" class="back">← Back to My Listings</RouterLink><template v-if="listing"><header class="heading"><div><span class="eyebrow">BROKER WORKSPACE</span><h1>Listing Details</h1><p>Inspect property information and listing status.</p></div><RouterLink v-if="editable" :to="`/broker/listings/${id}/edit`" class="button"><Pencil :size="17"/> Edit Draft</RouterLink></header><div class="notice"><strong>Status: {{ listing.status }}</strong> — This status reflects the current listing record returned by the server.</div><div class="grid"><div class="column"><section class="panel image"><img v-if="listing.images[0]" :src="listing.images[0]" :alt="listing.title"/><div v-else class="image-placeholder"><Building2 :size="35"/><strong>No Photo Available</strong></div></section><section class="panel"><h2>{{ listing.title }}</h2><p class="line"><MapPin :size="17"/> {{ listing.location || 'Location not specified' }}</p><div class="details"><div><span>Property Type</span><strong>{{ listing.propertyType }}</strong></div><div><span>Listing Type</span><strong>{{ listing.listingType }}</strong></div><div><span>Barangay</span><strong>{{ listing.barangay || 'Not specified' }}</strong></div><div><span>Property ID</span><strong>#{{ listing.id }}</strong></div></div></section><section class="panel"><h2>Description</h2><p>{{ listing.description || 'No description provided.' }}</p></section></div><aside class="column"><section class="panel"><h2>Pricing & Area</h2><strong class="price">{{ listing.price>0 ? formatBrokerPrice(listing.price) : 'Price not specified' }}</strong><p class="line"><Ruler :size="17"/> {{ listing.area>0 ? listing.area.toLocaleString('en-PH')+' sq. m.' : 'Area not specified' }}</p></section><section class="panel"><h2>Listing Activity</h2><p class="line"><CalendarDays :size="17"/> Created: {{ listing.dateCreated }}</p><p class="line"><MessageSquare :size="17"/> Inquiries: {{ listing.inquiries }}</p></section></aside></div></template><div v-else class="panel"><h1>Listing Not Found</h1><p>No listing with this ID is available to your account.</p><RouterLink to="/broker/listings">Back to Listings</RouterLink></div></main></AppSidebar></template>
